-- Recovery Workbench physical schema, PostgreSQL. Service rwb-source-data (P1, Source data), wave 1. Version 9.
-- Change log: 9, 27 November 2026, D-RCV-60 P1 developer readiness (RD-P1 register); targeted edits.
-- Change log: 7, 22 November 2026, D-RCV-60 microservice realignment, T3 Code / OpenCode / DeepSeek v4.1 Flash.
-- Schema rwb_source_data; login rwb_source_data; REST base /api/recovery/source-data/v1; topic rwb.source-data.events.v1; queue rwb-source-data.
-- Source: 06 Data/Recovery Workbench Physical Schema v6.sql (read only). Table, index, comment and seed text is copied unchanged; only the schema and the foreign keys change.
-- Tables in this file: 20 (case_list_row and lake_copy_watermark retired; four P1 tables added by RD-P1-020 and RD-P1-021). Owned by this service: 20. Platform library objects created here as well: 4.
-- Owner for every object comes from Recovery Workbench Microservice Ownership Map v1 (D-RCV-60).
-- Cross-owner references: a foreign key whose two tables have different owners in the Ownership Map is cut to a plain uuid column; integrity is through the owner's API contract (see README.md).

CREATE SCHEMA IF NOT EXISTS rwb_source_data;
SET search_path TO rwb_source_data;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ---------------------------------------------------------------------------
-- Platform library objects (owner PLT in the Ownership Map; DP-09, RWB-PLT-TE006-CON).
-- Created in every service schema. No foreign key to a business table.
-- decision_record (DP-03 library object, Architecture v5 slide 20; RD-P1-068 rule 8): rwb_source_data has the local decision record table
-- like every service. It is created once, by the shared library migration of RWB-PLT-E1027-CON, so this script does not create it.
-- Its DDL is in no schema file: Pending, owner platform lead (library owner), GAP-3316. Do not hand-write it here.
-- ---------------------------------------------------------------------------

-- Outbox event: An application event or outbound work request written in the same transaction as the change.
CREATE TABLE outbox_event (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    event_type varchar(40) NOT NULL,
    schema_version integer NOT NULL,
    case_id uuid,  -- cross-service reference: rwb_case.recovery_case(id); integrity through the owner's contract
    case_seq bigint,
    idempotency_key varchar(120) NOT NULL,
    payload jsonb NOT NULL,
    actor_ref varchar(64),
    occurred_at timestamptz NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_outbox_event UNIQUE (case_seq, idempotency_key)
);

-- Outbox delivery: The delivery of one outbox event to one consumer, with its retries.
CREATE TABLE outbox_delivery (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    event_id uuid NOT NULL,
    consumer varchar(60) NOT NULL,
    status varchar(12) NOT NULL DEFAULT 'PENDING',
    attempt_count integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL,
    last_error_code varchar(40),
    delivered_at timestamptz,
    task_id uuid,  -- cross-service reference: rwb_case.task(id); integrity through the owner's contract
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_outbox_delivery UNIQUE (event_id, consumer)
);

-- Processed event: An event or work key a consumer has already processed, so a repeat is ignored and counted.
CREATE TABLE processed_event (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    consumer varchar(60) NOT NULL,
    idempotency_key varchar(120) NOT NULL,
    event_id uuid,
    hit_count integer NOT NULL DEFAULT 1,
    last_seen_at timestamptz,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_processed_event UNIQUE (consumer, idempotency_key)
);

-- Idempotency key: The stored response of an API request sent with an Idempotency-Key header, kept 24 hours.
CREATE TABLE idempotency_key (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    idempotency_key uuid NOT NULL,
    endpoint varchar(100) NOT NULL,
    request_hash char(64) NOT NULL,
    response jsonb NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_idempotency_key UNIQUE (idempotency_key)
);

-- Interaction: One entry in the interaction ledger: a contact, letter, promise, payment or hand-over.
CREATE TABLE interaction (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    case_id uuid NOT NULL,  -- cross-service reference: rwb_case.recovery_case(id); integrity through the owner's contract
    person_key varchar(255),
    occurred_at timestamptz NOT NULL,
    channel varchar(15),
    direction varchar(8),
    action_code varchar(10),
    contact_result varchar(20),
    promise_amount numeric(18,2),
    promise_date date,
    summary varchar(2000),
    conduct_check varchar(15),
    source_system varchar(10) NOT NULL DEFAULT 'WORKBENCH',
    event_code varchar(40),
    actor_type varchar(10),
    actor_ref varchar(64),
    source_ref varchar(60),
    idempotency_key varchar(120),
    case_seq bigint,
    decision_log_id uuid,  -- cross-service reference: rwb_decision.decision_log_entry(id); integrity through the owner's contract
    corrects_entry_id uuid,
    contact_key varchar(255),
    from_holder_ref varchar(60),
    to_holder_ref varchar(60),
    treatment_id uuid,  -- cross-service reference: rwb_treatment.treatment(id); integrity through the owner's contract
    proceeds_id uuid,  -- cross-service reference: rwb_payment.proceeds(id); integrity through the owner's contract
    document_id uuid,  -- cross-service reference: rwb_document.document(id); the ledger contract's documentId
    retention_class varchar(10),
    delivery_status varchar(15),
    external_ref varchar(60),
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_interaction UNIQUE (idempotency_key)
);

-- Data product: One of the 14 data products, with its single system of record, owner and refresh cycle.
CREATE TABLE data_product (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    product_code varchar(25) NOT NULL,
    product_name varchar(80) NOT NULL,
    definition varchar(400) NOT NULL,
    system_of_record varchar(200) NOT NULL,
    owner_role varchar(20) NOT NULL,
    owner_user_id uuid,
    refresh_cycle varchar(10) NOT NULL,
    expected_by varchar(20),
    valid_from date NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_data_product UNIQUE (product_code)
);

-- Data product access: Which role may read which data product, by version.
CREATE TABLE data_product_access (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    product_code varchar(25) NOT NULL,
    role_code varchar(20) NOT NULL,
    can_read boolean NOT NULL DEFAULT false,
    access_version varchar(20) NOT NULL,
    valid_from date NOT NULL,
    valid_to date,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_data_product_access UNIQUE (product_code, role_code, access_version)
);

-- Data product load: The freshness stamp of a data product for one business date.
CREATE TABLE data_product_load (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    product_code varchar(25) NOT NULL,
    source_system varchar(40) NOT NULL,
    business_date date NOT NULL,
    source_extracted_at timestamptz NOT NULL,
    loaded_at timestamptz NOT NULL,
    status varchar(10) NOT NULL DEFAULT 'LOADED',
    stale_flagged_at timestamptz,
    duplicate_count integer NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_data_product_load UNIQUE (product_code, business_date)
);

-- Data contract: A versioned data contract with one source system, confirmed by its system owner.
CREATE TABLE data_contract (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    contract_code varchar(20) NOT NULL,
    source_system varchar(80) NOT NULL,
    interface_id varchar(40) NOT NULL,
    contract_version integer NOT NULL,
    status varchar(10) NOT NULL DEFAULT 'DRAFT',
    confirmed_by_role varchar(80),
    confirmed_on date,
    confirmation_document_ref varchar(400),
    published_at timestamptz,
    published_by uuid,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_data_contract UNIQUE (contract_code, contract_version)
);

-- Sys objects: The metadata registry of entities: one row per object in the data dictionary.
CREATE TABLE sys_objects (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    object_name varchar(60) NOT NULL,
    business_name varchar(120) NOT NULL,
    subject_area varchar(10) NOT NULL,
    data_product varchar(10),
    system_of_record varchar(120) NOT NULL,
    description varchar(400) NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_sys_objects UNIQUE (object_name)
);

-- Sys fields: The metadata registry of fields: the data dictionary held as data.
CREATE TABLE sys_fields (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    field_id varchar(16) NOT NULL,
    object_name varchar(60) NOT NULL,
    field_name varchar(60) NOT NULL,
    data_type varchar(12) NOT NULL,
    physical_type varchar(30) NOT NULL,
    is_mandatory boolean NOT NULL,
    lov_code varchar(30),
    references_object varchar(60),
    source_system varchar(80) NOT NULL,
    source_field varchar(80),
    is_personal boolean NOT NULL DEFAULT false,
    description varchar(400) NOT NULL,
    owner_role varchar(20),
    refresh_cycle varchar(30),
    late_behavior varchar(200),
    interface_id varchar(10),
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_sys_fields UNIQUE (field_id)
);

-- Sys field version: Each version of a field definition, kept when the definition changes.
CREATE TABLE sys_field_version (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    field_id varchar(16) NOT NULL,
    field_version integer NOT NULL,
    definition jsonb NOT NULL,
    change_reason varchar(400) NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_sys_field_version UNIQUE (field_id, field_version)
);

