-- Retirement note: lake_copy_watermark has no target. The data lake is removed (Architecture v5 slide 37; DP-17)
-- and JOB-13 is continuous Kafka ingest in rwb-decision (Architecture v5 slide 44), so P1 never creates this
-- table (Ownership Map ruling ASM-0079; RD-P1-021). The DDL is kept here as comment text; see GAP-0114.

-- Dp treatment: The copy of each treatment for a business date in the DP04 data product.
CREATE TABLE dp_treatment (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    treatment_id uuid NOT NULL,  -- cross-service reference: rwb_treatment.treatment(id); integrity through the owner's contract
    case_id uuid NOT NULL,  -- cross-service reference: rwb_case.recovery_case(id); integrity through the owner's contract
    decision_log_id uuid,  -- cross-service reference: rwb_decision.decision_log_entry(id); integrity through the owner's contract
    treatment_type varchar(20) NOT NULL,
    proposed_by varchar(10) NOT NULL,
    proposed_at timestamptz NOT NULL,
    offer_amount numeric(18,2),
    haircut_amount numeric(18,2),
    installments integer,
    valid_until date,
    approval_level varchar(4),
    booked_at timestamptz,
    outcome varchar(12),
    outcome_at timestamptz,
    business_date date NOT NULL,
    contract_no varchar(20),
    contract_date date,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_dp_treatment UNIQUE (business_date, treatment_id)
);

-- Dp guarantee claim: The copy of each guarantee claim for a business date in the DP04 data product.
CREATE TABLE dp_guarantee_claim (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    guarantee_claim_id uuid NOT NULL,  -- cross-service reference: rwb_guarantee.guarantee_claim(id); integrity through the owner's contract
    case_id uuid NOT NULL,  -- cross-service reference: rwb_case.recovery_case(id); integrity through the owner's contract
    claim_type varchar(25) NOT NULL,
    claim_deadline date NOT NULL,
    claimed_amount numeric(18,2) NOT NULL,
    filed_at date,
    paid_amount numeric(18,2),
    status varchar(12) NOT NULL,
    business_date date NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_dp_guarantee_claim UNIQUE (business_date, guarantee_claim_id)
);

-- Efs ledger outcome: Which EFS action codes enter the interaction ledger and on which channel.
CREATE TABLE efs_ledger_outcome (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    action_code varchar(10) NOT NULL,
    channel varchar(15) NOT NULL DEFAULT 'CALL',
    in_ledger boolean NOT NULL DEFAULT true,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_efs_ledger_outcome UNIQUE (action_code)
);

-- Party extension: Workbench flags about an ACE customer, keyed by person_key.
CREATE TABLE party_ext (
    person_key varchar(255) PRIMARY KEY,
    vulnerable boolean NOT NULL DEFAULT false,
    deceased_override boolean NOT NULL DEFAULT false,
    bankruptcy boolean NOT NULL DEFAULT false,
    fraud_flag boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid
);

-- Contact point extension: consent and contact quality for an ACE phone, email or address.
CREATE TABLE contact_point_ext (
    contact_key varchar(255) PRIMARY KEY,
    contact_type varchar(10) NOT NULL,
    consent_given boolean NOT NULL DEFAULT false,
    consent_at timestamptz,
    verified_at timestamptz,
    failed_count integer NOT NULL DEFAULT 0,
    source varchar(20) NOT NULL DEFAULT 'WORKBENCH',
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    person_key varchar(255),  -- business key, no foreign key (RWB-P1-E2022-APP)
    CONSTRAINT ck_contact_point_ext_type CHECK (contact_type IN ('PHONE', 'EMAIL', 'ADDRESS')),
    CONSTRAINT ck_contact_point_ext_failed_count CHECK (failed_count >= 0)
);

-- Account extension: Workbench state about an ACE account, keyed by account_key.
CREATE TABLE account_ext (
    account_key varchar(255) PRIMARY KEY,
    dispute_open boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid
);

-- Valuation extension: the Workbench's decision about an ACE appraisal, keyed by valuation_key.
CREATE TABLE valuation_ext (
    valuation_key varchar(255) PRIMARY KEY,
    accepted boolean NOT NULL DEFAULT false,
    accepted_at timestamptz,
    accepted_by uuid,
    valuer_partner_id uuid,
    stale_flag boolean NOT NULL DEFAULT false,
    age_days integer,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid
);

-- Data product source: One row per data product and ACE source system that feeds it (RD-P1-021).
CREATE TABLE data_product_source (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    product_code varchar(25) NOT NULL,
    source_system varchar(20) NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_data_product_source UNIQUE (product_code, source_system)
);

-- Job run: One row per attempt of a job that runs inside rwb-source-data (RD-P1-020 A). Created by the RWB-P1-AD018-APP migration.
CREATE TABLE job_run (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    job_type varchar(60) NOT NULL,
    business_date date NOT NULL,
    run_no integer NOT NULL DEFAULT 1,
    status varchar(10) NOT NULL DEFAULT 'PENDING',  -- LOV-JOB-RUN
    workflow_id varchar(200),
    started_at timestamptz,
    finished_at timestamptz,
    duration_minutes integer,
    message_id varchar(20),
    requested_by uuid,
    idempotency_key varchar(120),
    rerun_of_id uuid,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_job_run UNIQUE (job_type, business_date, run_no),
    CONSTRAINT uk_job_run_idempotency UNIQUE (idempotency_key)
);

-- Job run check: One row per check of one run; carries Job.checks; append only (RD-P1-020 B). Created by the RWB-P1-AD018-APP migration.
CREATE TABLE job_run_check (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    job_run_id uuid NOT NULL,
    check_code varchar(30) NOT NULL,  -- LOV-JOB-CHECK
    check_result varchar(8) NOT NULL,  -- LOV-REC-RESULT
    check_count integer,
    expected_count integer,
    is_active boolean NOT NULL DEFAULT true,
    state varchar(40),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_job_run_check UNIQUE (job_run_id, check_code)
);

-- Business day readiness: One row per business date for which the readiness call or fallback poll arrived (RD-P1-020 F). Created by the RWB-P1-E1013-APP migration.
CREATE TABLE business_day_readiness (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    business_date date NOT NULL,
    state varchar(10) NOT NULL DEFAULT 'RUNNING',  -- LOV-READINESS; the standard column state is not repeated for this table
    received_at timestamptz NOT NULL,
    changed_at timestamptz NOT NULL,
    idempotency_key varchar(120),  -- UUID Idempotency-Key of the first readiness call (RD-P1-001)
    is_active boolean NOT NULL DEFAULT true,
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    CONSTRAINT uk_business_day_readiness UNIQUE (business_date)
);

-- ---------------------------------------------------------------------------
-- Foreign keys kept inside this service (same owner).
-- ---------------------------------------------------------------------------

ALTER TABLE interaction ADD CONSTRAINT fk_interaction_corrects_entry_id FOREIGN KEY (corrects_entry_id) REFERENCES interaction (id) ON DELETE RESTRICT;
ALTER TABLE processed_event ADD CONSTRAINT fk_processed_event_event_id FOREIGN KEY (event_id) REFERENCES outbox_event (id) ON DELETE RESTRICT;
ALTER TABLE sys_fields ADD CONSTRAINT fk_sys_fields_object_name FOREIGN KEY (object_name) REFERENCES sys_objects (object_name) ON DELETE RESTRICT;
ALTER TABLE sys_objects ADD CONSTRAINT fk_sys_objects_data_product FOREIGN KEY (data_product) REFERENCES data_product (product_code) ON DELETE RESTRICT;
ALTER TABLE outbox_delivery ADD CONSTRAINT fk_outbox_delivery_event_id FOREIGN KEY (event_id) REFERENCES outbox_event (id) ON DELETE RESTRICT;
