COMMENT ON COLUMN business_day_readiness.state IS 'Readiness state; RUNNING, DONE or LATE; this is the table state field';
COMMENT ON COLUMN business_day_readiness.received_at IS 'First arrival of the readiness call or fallback poll for the date';
COMMENT ON COLUMN business_day_readiness.changed_at IS 'Time of the last state change; returned by GET /business-days/{date}/status';
COMMENT ON COLUMN business_day_readiness.idempotency_key IS 'Idempotency-Key of the readiness call';
COMMENT ON COLUMN contact_point_ext.person_key IS 'Customer business key of the contact point';

